#include <stdio.h>
#define MAX 100

typedef struct { int arr[MAX]; int front, rear, size; } Queue;
void init(Queue* q) { q->front=0; q->rear=-1; q->size=0; }
void enqueue(Queue* q, int x) { q->arr[++q->rear]=x; q->size++; }
int dequeue(Queue* q) { q->size--; return q->arr[q->front++]; }
int front(Queue* q) { return q->arr[q->front]; }
int isEmpty(Queue* q) { return q->size==0; }

int main() {
    Queue q; init(&q);
    enqueue(&q,1); enqueue(&q,2); enqueue(&q,3);
    printf("Front: %d\n", front(&q));
    printf("Dequeue: %d\n", dequeue(&q));
    printf("Front now: %d\n", front(&q));
    return 0;
}

