#include <iostream>
#include <stack>
using namespace std;

// Queue using two stacks
class MyQueue {
    stack<int> s1, s2;
public:
    void push(int x) { s1.push(x); }
    int pop() {
        if (s2.empty()) { while (!s1.empty()) { s2.push(s1.top()); s1.pop(); } }
        int val = s2.top(); s2.pop(); return val;
    }
    int peek() {
        if (s2.empty()) { while (!s1.empty()) { s2.push(s1.top()); s1.pop(); } }
        return s2.top();
    }
    bool empty() { return s1.empty() && s2.empty(); }
};

int main() {
    MyQueue q;
    q.push(1); q.push(2); q.push(3);
    cout << q.pop() << endl;   // 1
    cout << q.peek() << endl;  // 2
    return 0;
}

