#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node* next; } Node;
typedef struct { Node *front, *rear; int size; } LLQueue;

void init(LLQueue* q) { q->front=q->rear=NULL; q->size=0; }
void enqueue(LLQueue* q, int x) {
    Node* n = malloc(sizeof(Node)); n->data=x; n->next=NULL;
    if (!q->rear) { q->front=q->rear=n; }
    else { q->rear->next=n; q->rear=n; }
    q->size++;
}
int dequeue(LLQueue* q) {
    Node* tmp = q->front; int val = tmp->data;
    q->front = q->front->next;
    if (!q->front) q->rear = NULL;
    free(tmp); q->size--; return val;
}
int main() {
    LLQueue q; init(&q);
    enqueue(&q,1); enqueue(&q,2); enqueue(&q,3);
    printf("%d\n", dequeue(&q)); // 1
    printf("%d\n", dequeue(&q)); // 2
    return 0;
}

