#include <iostream>
#include <queue>
#include <vector>
using namespace std;

// BFS on graph
void bfs(vector<vector<int>>& adj, int src, int n) {
    vector<bool> visited(n, false);
    queue<int> q;
    q.push(src); visited[src] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        cout << u << " ";
        for (int v : adj[u]) {
            if (!visited[v]) { visited[v]=true; q.push(v); }
        }
    }
    cout << endl;
}

int main() {
    int n = 5;
    vector<vector<int>> adj(n);
    adj[0]={1,2}; adj[1]={3}; adj[2]={4};
    bfs(adj, 0, n); // 0 1 2 3 4
    return 0;
}

